    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Validate config finiteness and positivity
if (!isfinite(mt_config.max_voltage_v) || !isfinite(mt_config.resistance_ohm) || 
    !isfinite(mt_config.capacity_j_k) || !isfinite(mt_config.thermal_resistance_k_w) || 
    !isfinite(mt_config.trip_temperature_k) || !isfinite(mt_config.reset_temperature_k)) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

if (mt_config.resistance_ohm <= 0.0 || mt_config.capacity_j_k <= 0.0 || 
    mt_config.thermal_resistance_k_w <= 0.0 || tel->dt_s <= 0.0) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Validate reset < trip
if (mt_config.reset_temperature_k >= mt_config.trip_temperature_k) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Validate max_trip_cycles <= 1000
if (mt_config.max_trip_cycles > 1000) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Validate winding temperature finiteness
if (!isfinite(mt_state.winding_temperature_k)) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Step 2: Handle Disabled (OFF) Case
if (!mt_input.enable) {
    mt_output.mode = MT_OFF;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    mt_state.trip_count = 0;
    return;
}

// Step 3: Limit Voltage Request
adcs_actuator_limit_t voltage_limit;
voltage_limit.min_value = -mt_config.max_voltage_v;
voltage_limit.max_value = mt_config.max_voltage_v;
voltage_limit.max_slew_per_s = 0.0;

double limited_voltage;
if (adcs_limit_scalar(tel->requested_voltage_v, &voltage_limit, &limited_voltage) != ADCS_OK) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

// Step 4: Thermal Model Calculation
double heating_w = (limited_voltage * limited_voltage) / mt_config.resistance_ohm;
double cooling_w = (mt_state.winding_temperature_k - tel->ambient_temperature_k) / mt_config.thermal_resistance_k_w;
double net_heat_w = heating_w - cooling_w;

double delta_temp = (net_heat_w * tel->dt_s) / mt_config.capacity_j_k;
double next_temp = mt_state.winding_temperature_k + delta_temp;

// Step 5: State Machine Logic
mt_mode_t next_mode = mt_state.mode;
double applied_voltage = 0.0;
uint32_t next_trip_count = mt_state.trip_count;

switch (mt_state.mode) {
    case MT_DRIVE:
        if (next_temp >= mt_config.trip_temperature_k) {
            if (mt_config.max_trip_cycles == 0 || mt_state.trip_count < mt_config.max_trip_cycles) {
                next_mode = MT_COOL;
                next_trip_count++;
                applied_voltage = 0.0;
            } else {
                next_mode = MT_FAULT;
                applied_voltage = 0.0;
            }
        } else {
            next_mode = MT_DRIVE;
            applied_voltage = limited_voltage;
        }
        break;

    case MT_COOL:
        if (next_temp > mt_config.reset_temperature_k) {
            next_mode = MT_COOL;
            applied_voltage = 0.0;
        } else {
            next_mode = MT_DRIVE;
            applied_voltage = 0.0;
        }
        break;

    case MT_FAULT:
        next_mode = MT_FAULT;
        applied_voltage = 0.0;
        break;

    case MT_OFF:
        next_mode = MT_OFF;
        applied_voltage = 0.0;
        break;

    default:
        next_mode = MT_FAULT;
        applied_voltage = 0.0;
        break;
}

// Update Outputs
mt_output.mode = next_mode;
mt_output.applied_voltage_v = applied_voltage;
mt_output.winding_temperature_k = next_temp;
mt_output.heating_w = heating_w;
mt_output.cooling_w = cooling_w;

// Update Internal State
mt_state.mode = next_mode;
mt_state.winding_temperature_k = next_temp;
mt_state.trip_count = next_trip_count;
